<script lang="ts">
 import type {Board} from '../shared/model';
 import {readiness} from '../shared/graph';
 let {board,selected,search,domain,status,scope,docPaths=new Set<string>(),onselect}:{board:Board;selected:string;search:string;domain:string;status:string;scope:string;docPaths?:ReadonlySet<string>;onselect:(id:string)=>void}=$props();
 let archives=$state(false);
 let tasks=$derived(board.tasks.filter(t=>(archives||!t.archived)&&(!search||t.title.toLowerCase().includes(search.toLowerCase()))&&(domain==='all'||t.domain===domain)&&(status==='all'||t.status===status)&&(scope==='all'||t.scope===scope)));
</script>
<div class="list-controls"><span>{tasks.length} matching tasks</span><label><input type="checkbox" bind:checked={archives}>Include archived ({board.tasks.filter(t=>t.archived).length})</label></div>
<table class="task-table"><thead><tr><th>TASK</th><th>AREA</th><th>STATE</th><th class="optional">SPEC</th><th class="optional">MILESTONE</th><th class="optional">BLOCKED BY / GATES</th></tr></thead>
<tbody>{#each tasks as task}<tr class:selected={selected===task.id}><td><button onclick={()=>onselect(task.id)}>{task.title}<small>{task.scope}{task.archived?' · archived':''}</small></button></td><td>{board.domains.find(d=>d.id===task.domain)?.name}</td><td>{readiness(board,task.id)}</td><td class="optional">{#if !task.specs.length}<span class="spec-chip none" title="Advisory: this task records no specification link">no spec</span>{:else}{#each task.specs as spec}<span class="spec-chip" class:broken={!docPaths.has(spec.path)} title={spec.path+(spec.anchor?'#'+spec.anchor:'')}>{spec.path.split('/').pop()}{spec.anchor?'#'+spec.anchor:''}</span>{/each}{/if}</td><td class="optional">{board.milestones.find(m=>m.id===task.milestone)?.name??'Independent'}</td><td class="optional">{#each board.relationships.filter(e=>e.kind==='blocks'&&e.target===task.id) as e}<button class="prereq" onclick={()=>onselect(e.source)}>{board.tasks.find(t=>t.id===e.source)?.title}</button>{/each}{#each task.gates.filter(g=>g.state==='open') as gate}<span class="gate-label">⊘ {gate.label}</span>{/each}</td></tr>{/each}</tbody></table>
{#if !tasks.length}<div class="empty"><h2>No matching tasks</h2><p>Change filters or include archived work. Hidden prerequisites still affect readiness.</p></div>{/if}
<style>.list-controls{display:flex;justify-content:space-between;align-items:center;padding:8px 16px;border-bottom:1px solid var(--line);font-size:11px;color:var(--muted)}.list-controls label{font-size:11px}small{display:block;margin-top:5px;color:var(--muted);font-size:9px}.prereq,.gate-label{display:block;font-size:9px;max-width:240px;margin-bottom:5px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.gate-label{color:var(--danger)}td:first-child{max-width:400px}</style>
